<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>License Activation</title><link rel="stylesheet" href="/assets/css/legacy-style.css"><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="card"><h1>License Activation</h1><?php foreach (($errors ?? []) as $error): ?><p class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endforeach; ?><form method="post" action="/license-activation"><input type="hidden" name="_token" value="<?= htmlspecialchars($token, ENT_QUOTES, 'UTF-8') ?>"><label>License Key</label><input name="license_key" required><label>Domain</label><input name="domain" value="<?= htmlspecialchars($company['subdomain'] ?? 'localhost', ENT_QUOTES, 'UTF-8') ?>.localhost" required><label>Expiry Date</label><input name="expiry_date" type="date" value="<?= date('Y-m-d', strtotime('+365 days')) ?>" required><button type="submit">Activate License</button></form><p><a href="/license-manager">Back to license manager</a></p></main></body></html>
